local CanvasStretcherMaker = {}
local PRODUCTS = {
    iron_canvas_stretcher = { name = "Železni napenjalec platna", ironCost = 2, woodCost = 3, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železni napenjalec za platna." },
    bronze_canvas_stretcher = { name = "Bronast napenjalec platna", bronzeCost = 2, ironCost = 1, woodCost = 3, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronast napenjalec za atelje." },
    silver_canvas_stretcher = { name = "Srebrni napenjalec platna", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 11, cost = 950, prestige = 10, happiness = 4, description = "Srebrni napenjalec za plemiške slikarje." },
    gilded_canvas_stretcher = { name = "Pozlačeni napenjalec platna", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 15, cost = 2050, prestige = 19, happiness = 5, description = "Pozlačeni napenjalec za dvorne slikarje." },
    jewel_set_canvas_stretcher = { name = "Draguljasti napenjalec platna", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 19, cost = 4400, prestige = 35, happiness = 7, description = "Draguljasti napenjalec za kraljeve slikarje." },
    royal_sovereign_canvas_stretcher = { name = "Kraljevski suvereni napenjalec platna", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 26, cost = 9500, prestige = 67, happiness = 13, description = "Suvereni napenjalec z biseri za krono." },
}
local BUILDINGS = {
    canvas_workshop = { name = "Napenjalna delavnica", cost = { gold = 325, wood = 190, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    canvas_house = { name = "Napenjalna hiša", cost = { gold = 1180, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_canvas_atelier = { name = "Mojstrski napenjalni atelje", cost = { gold = 2980, wood = 430, stone = 520, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_canvas_palace = { name = "Suverena napenjalna palača", cost = { gold = 12900, wood = 660, stone = 830, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CanvasStretcherMaker.ironStock = 12; CanvasStretcherMaker.bronzeStock = 10; CanvasStretcherMaker.woodStock = 18; CanvasStretcherMaker.leatherStock = 10; CanvasStretcherMaker.silverStock = 8; CanvasStretcherMaker.goldStock = 6; CanvasStretcherMaker.jewelStock = 4; CanvasStretcherMaker.pearlStock = 4
CanvasStretcherMaker.productStock = {}; CanvasStretcherMaker.buildings = {}; CanvasStretcherMaker.maker = nil; CanvasStretcherMaker.activeMaking = {}; CanvasStretcherMaker.totalProducts = 0; CanvasStretcherMaker.dayTimer = 0
function CanvasStretcherMaker.init() CanvasStretcherMaker.ironStock=12; CanvasStretcherMaker.bronzeStock=10; CanvasStretcherMaker.woodStock=18; CanvasStretcherMaker.leatherStock=10; CanvasStretcherMaker.silverStock=8; CanvasStretcherMaker.goldStock=6; CanvasStretcherMaker.jewelStock=4; CanvasStretcherMaker.pearlStock=4; CanvasStretcherMaker.productStock={}; CanvasStretcherMaker.buildings={}; CanvasStretcherMaker.maker=nil; CanvasStretcherMaker.activeMaking={}; CanvasStretcherMaker.totalProducts=0; CanvasStretcherMaker.dayTimer=0; print("[CanvasStretcherMaker] Royal Canvas Stretcher Maker System initialized (6 products, 4 buildings)") end
function CanvasStretcherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CanvasStretcherMaker.maker={name=n or ("Napenjalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napenjalec najet: %s (spretnost: %d)",CanvasStretcherMaker.maker.name,s),"success") end; return true end
function CanvasStretcherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CanvasStretcherMaker.build(id) local ok,e=CanvasStretcherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CanvasStretcherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CanvasStretcherMaker.getQualityBonus() local b=0; for _,bd in ipairs(CanvasStretcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CanvasStretcherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CanvasStretcherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CanvasStretcherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CanvasStretcherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CanvasStretcherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CanvasStretcherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CanvasStretcherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CanvasStretcherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CanvasStretcherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CanvasStretcherMaker.buildings==0 then return false,"Potrebna napenjalna delavnica" end; if not CanvasStretcherMaker.maker then return false,"Potreben napenjalec" end; return true end
function CanvasStretcherMaker.make(pt,qty) qty=qty or 1; local ok,e=CanvasStretcherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CanvasStretcherMaker.ironStock=CanvasStretcherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CanvasStretcherMaker.bronzeStock=CanvasStretcherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CanvasStretcherMaker.woodStock=CanvasStretcherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CanvasStretcherMaker.leatherStock=CanvasStretcherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CanvasStretcherMaker.silverStock=CanvasStretcherMaker.silverStock-d.silverCost*qty end; if d.goldCost then CanvasStretcherMaker.goldStock=CanvasStretcherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CanvasStretcherMaker.jewelStock=CanvasStretcherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CanvasStretcherMaker.pearlStock=CanvasStretcherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CanvasStretcherMaker.maker then t=math.max(1,t-math.floor(CanvasStretcherMaker.maker.skill/13)) end; table.insert(CanvasStretcherMaker.activeMaking,{id="canvas_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CanvasStretcherMaker.completeMaking(m) local q=1.0+(CanvasStretcherMaker.getQualityBonus()/100); if CanvasStretcherMaker.maker then q=q+(CanvasStretcherMaker.maker.skill/140) end; q=math.min(2.5,q); CanvasStretcherMaker.productStock[m.productType]=(CanvasStretcherMaker.productStock[m.productType] or 0)+m.quantity; CanvasStretcherMaker.totalProducts=CanvasStretcherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CanvasStretcherMaker.maker then CanvasStretcherMaker.maker.itemsMade=CanvasStretcherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CanvasStretcherMaker.maker.skill=math.min(100,CanvasStretcherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napenjalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"canvas.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CanvasStretcherMaker.update(dt) if not _G.state then return end; CanvasStretcherMaker.dayTimer=CanvasStretcherMaker.dayTimer+dt; if CanvasStretcherMaker.dayTimer>=30 then CanvasStretcherMaker.dayTimer=0; for i=#CanvasStretcherMaker.activeMaking,1,-1 do local m=CanvasStretcherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CanvasStretcherMaker.completeMaking(m); table.remove(CanvasStretcherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CanvasStretcherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CanvasStretcherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CanvasStretcherMaker.getStats() return {ironStock=CanvasStretcherMaker.ironStock,bronzeStock=CanvasStretcherMaker.bronzeStock,woodStock=CanvasStretcherMaker.woodStock,leatherStock=CanvasStretcherMaker.leatherStock,silverStock=CanvasStretcherMaker.silverStock,goldStock=CanvasStretcherMaker.goldStock,jewelStock=CanvasStretcherMaker.jewelStock,pearlStock=CanvasStretcherMaker.pearlStock,productStock=CanvasStretcherMaker.productStock,numBuildings=#CanvasStretcherMaker.buildings,hasMaker=CanvasStretcherMaker.maker~=nil,makerName=CanvasStretcherMaker.maker and CanvasStretcherMaker.maker.name or "—",makerSkill=CanvasStretcherMaker.maker and CanvasStretcherMaker.maker.skill or 0,activeMaking=#CanvasStretcherMaker.activeMaking,totalProducts=CanvasStretcherMaker.totalProducts} end
return CanvasStretcherMaker
